import React, { useEffect, useState } from 'react';
import Auth from '../Components/Auth';
import InviteEditor from '../Components/InviteEditor';
import MarkdownEditor from '../Components/MarkdownEditor';
import { auth, db, storage } from '../firebase';
import { collection, getDocs, doc, updateDoc, addDoc, getDoc } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { cmsSchema } from '../schemas';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';

const typesOptions = [
    "Print Writing", "Online Writing", "Essay", "Curation",
    "Copy editing", "Translation", "Conversation", "Talk"
];

const Admin = () => {
    const [user, setUser] = useState(null);
    const [userRole, setUserRole] = useState(null);
    const [checkingAuth, setCheckingAuth] = useState(true);
    const [data, setData] = useState({});
    const [activeDoc, setActiveDoc] = useState(null);
    const [modalData, setModalData] = useState(null);
    const [collectionName, setCollectionName] = useState(null);
    const [saving, setSaving] = useState(false);
    const [showNewModal, setShowNewModal] = useState(false);
    const [newProjectData, setNewProjectData] = useState({
        name: "",
        details: "",
        text: "",
        image_header: "",
        header_credits: "",
        abstract: "",
        types: [],
        link: "",
        created_on: { seconds: Math.floor(Date.now() / 1000) },
        images_in_article: []
    });

    useEffect(() => {
        const unsub = auth.onAuthStateChanged(async (u) => {
            if (u) {
                const roleDoc = await getDoc(doc(db, 'roles', u.uid));
                const role = roleDoc.exists() ? roleDoc.data().role : null;
                setUser(u);
                setUserRole(role);
            }
            setCheckingAuth(false);
        });
        return unsub;
    }, []);

    useEffect(() => {
        if (!user) return;
        const fetchData = async () => {
            const newData = {};
            for (const colName of Object.keys(cmsSchema)) {
                const snapshot = await getDocs(collection(db, colName));
                newData[colName] = snapshot.docs.map(doc => ({
                    id: doc.id,
                    ...doc.data()
                }));
            }
            setData(newData);
        };
        fetchData();
    }, [user]);

    const handleLogout = () => auth.signOut();

    const openEditor = (colName, doc) => {
        setActiveDoc(doc);
        setCollectionName(colName);
        setModalData({ ...doc });
    };

    const closeEditor = () => {
        setActiveDoc(null);
        setModalData(null);
        setCollectionName(null);
    };

    const handleFieldChange = (field, value) => {
        setModalData(prev => ({ ...prev, [field]: value }));
    };

    const handleNewFieldChange = (field, value) => {
        setNewProjectData(prev => ({ ...prev, [field]: value }));
    };

    const handleImageUpload = async (field, file, isNew = false) => {
        const id = isNew ? `new-${Date.now()}` : activeDoc.id;
        const storageRef = ref(storage, `${collectionName}/${id}/${file.name}`);
        await uploadBytes(storageRef, file);
        const url = await getDownloadURL(storageRef);
        isNew ? handleNewFieldChange(field, url) : handleFieldChange(field, url);
    };

    const saveChanges = async () => {
        setSaving(true);
        const docRef = doc(db, collectionName, activeDoc.id);
        await updateDoc(docRef, modalData);
        setData(prev => ({
            ...prev,
            [collectionName]: prev[collectionName].map(d =>
                d.id === activeDoc.id ? { ...modalData } : d
            )
        }));
        closeEditor();
        setSaving(false);
    };

    const submitNewProject = async () => {
        const docRef = await addDoc(collection(db, "projects"), newProjectData);
        setData(prev => ({
            ...prev,
            projects: [
                ...(prev.projects || []),
                { id: docRef.id, ...newProjectData }
            ]
        }));
        setShowNewModal(false);
        setNewProjectData({
            name: "",
            details: "",
            text: "",
            image_header: "",
            header_credits: "",
            abstract: "",
            types: [],
            link: "",
            created_on: { seconds: Math.floor(Date.now() / 1000) },
            images_in_article: []
        });
    };

    const renderFieldInput = (fieldName, fieldConfig, dataObj, onChange, isNew = false) => {
        const value = dataObj[fieldName];

        if (fieldName === 'text') {
            return <MarkdownEditor value={value} onChange={(val) => onChange(fieldName, val)} />;
        }

        if (fieldConfig.type === 'image') {
            return (
                <div className="flex flex-col items-start gap-2">
                    {value && (
                        <a href={value} target="_blank" rel="noopener noreferrer">
                            <img src={value} alt="preview" className="h-32 object-contain" />
                        </a>
                    )}
                    <input type="file" accept="image/*" onChange={(e) => handleImageUpload(fieldName, e.target.files[0], isNew)} />
                </div>
            );
        }

        if (fieldName === 'images_in_article') {
            return (
                <div className="space-y-2 w-full">
                    {(value || []).map((url, i) => (
                        <div key={i} className="flex items-center gap-2">
                            <a href={url} target="_blank" rel="noopener noreferrer">
                                <img src={url} className="h-20 object-contain" />
                            </a>
                            <button className="text-sm text-red-500" onClick={() => {
                                const updated = value.filter((_, idx) => idx !== i);
                                onChange(fieldName, updated);
                            }}>Remove</button>
                        </div>
                    ))}
                    <input type="file" accept="image/*" onChange={async (e) => {
                        const file = e.target.files[0];
                        const storageRef = ref(storage, `projects/${Date.now()}-inline-${file.name}`);
                        await uploadBytes(storageRef, file);
                        const url = await getDownloadURL(storageRef);
                        onChange(fieldName, [...(value || []), url]);
                    }} />
                </div>
            );
        }

        if (fieldName === 'types') {
            return (
                <div className="flex flex-wrap gap-4">
                    {typesOptions.map(option => (
                        <label key={option} className="flex items-center gap-2 text-sm">
                            <input
                                type="checkbox"
                                checked={(value || []).includes(option)}
                                onChange={(e) => {
                                    const updated = e.target.checked
                                        ? [...(value || []), option]
                                        : (value || []).filter(o => o !== option);
                                    onChange(fieldName, updated);
                                }}
                            />
                            {option}
                        </label>
                    ))}
                </div>
            );
        }

        if (fieldName === 'created_on') {
            return (
                <DatePicker
                    selected={value?.seconds ? new Date(value.seconds * 1000) : new Date()}
                    onChange={(date) => onChange(fieldName, { seconds: Math.floor(date.getTime() / 1000) })}
                    className="border p-2 rounded w-full"
                    dateFormat="dd/MM/yyyy"
                />
            );
        }

        return (
            <textarea
                className="w-full border p-2 rounded resize-none min-h-[60px] font-serif"
                value={value || ''}
                onChange={(e) => onChange(fieldName, e.target.value)}
            />
        );
    };

    if (checkingAuth) return <div id="update">Checking authentication…</div>;
    if (!user || !userRole) return <Auth onLogin={(user, role) => { setUser(user); setUserRole(role); }} />;

    return (
        <div id="Work" className="section overflow-auto px-6 font-sans">
            <div className="flex justify-between items-center mb-6">
                <div
                    id="AdminLogo"
                    className="logo"
                    style={{
                        backgroundImage: 'url("./Logo.png")',
                    }}
                />
                <div className="space-x-4 flex items-center">
                    {userRole === 'admin' && <InviteEditor />}
                    <button onClick={() => setShowNewModal(true)} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 text-sm">+ New Project</button>
                    <button onClick={handleLogout} className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 text-sm">Logout</button>
                </div>
            </div>

            {Object.entries(cmsSchema).map(([colName, config]) => (
                <div key={colName} className="mb-20 overflow-x-auto">
                    <h2 className="text-2xl mb-4">{config.label}</h2>
                    <table className="min-w-[1000px] border border-gray-300 text-sm">
                        <thead className="bg-gray-100 text-left">
                            <tr>
                                <th className="border p-2">ID</th>
                                {Object.keys(config.fields).map((fieldName) => (
                                    <th key={fieldName} className="border p-2">{fieldName.replace(/_/g, ' ')}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {data[colName]?.map((doc) => (
                                <tr key={doc.id} className="hover:bg-gray-100 cursor-pointer" onClick={() => openEditor(colName, doc)}>
                                    <td className="border p-2 text-xs">{doc.id}</td>
                                    {Object.entries(config.fields).map(([fieldName]) => (
                                        <td key={fieldName} className="border p-2 truncate max-w-[200px]">
                                            {fieldName === 'created_on'
                                                ? doc[fieldName]?.seconds
                                                    ? new Date(doc[fieldName].seconds * 1000).toLocaleDateString()
                                                    : '—'
                                                : Array.isArray(doc[fieldName])
                                                    ? doc[fieldName].join(', ')
                                                    : typeof doc[fieldName] === 'string'
                                                        ? doc[fieldName].slice(0, 50)
                                                        : '—'}
                                        </td>
                                    ))}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            ))}

            {activeDoc && modalData && (
                <Modal
                    data={modalData}
                    fields={cmsSchema[collectionName].fields}
                    onChange={handleFieldChange}
                    onSave={saveChanges}
                    onClose={closeEditor}
                    saving={saving}
                    renderFieldInput={renderFieldInput}
                />
            )}

            {showNewModal && (
                <Modal
                    data={newProjectData}
                    fields={cmsSchema.projects.fields}
                    onChange={handleNewFieldChange}
                    onSave={submitNewProject}
                    onClose={() => setShowNewModal(false)}
                    saving={saving}
                    renderFieldInput={renderFieldInput}
                />
            )}
        </div>
    );
};

const Modal = ({ data, fields, onChange, onSave, onClose, saving, renderFieldInput }) => (
    <div className="fixed inset-0 bg-black bg-opacity-60 flex justify-center items-center z-50">
        <div className="bg-white rounded-lg w-[90vw] max-w-4xl h-[90vh] overflow-y-auto p-6 relative font-sans">
            <button onClick={onClose} className="absolute top-4 right-4 text-gray-600 hover:text-black">✕</button>
            <h2 className="text-2xl mb-4 font-semibold">Edit Entry</h2>
            {Object.entries(fields).map(([fieldName, fieldConfig]) => (
                <div key={fieldName} className="mb-6">
                    <label className="block font-semibold mb-2 capitalize">{fieldName.replace(/_/g, ' ')}</label>
                    {renderFieldInput(fieldName, fieldConfig, data, onChange)}
                </div>
            ))}
            <button onClick={onSave} disabled={saving} className="mt-4 bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700">
                {saving ? 'Saving...' : 'Save Changes'}
            </button>
        </div>
    </div>
);

export default Admin;