import React, { useState } from 'react';
import {
    signInWithEmailAndPassword,
    GoogleAuthProvider,
    signInWithPopup,
    sendPasswordResetEmail
} from 'firebase/auth';
import { getDoc, doc } from 'firebase/firestore';
import { auth, db } from '../firebase';

const Auth = ({ onLogin }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [status, setStatus] = useState(null);

    const handleEmailLogin = async () => {
        setStatus(null);
        try {
            const result = await signInWithEmailAndPassword(auth, email, password);
            const roleDoc = await getDoc(doc(db, 'roles', result.user.uid));
            const role = roleDoc.exists() ? roleDoc.data().role : null;
            onLogin(result.user, role);
        } catch (err) {
            setStatus(err.message);
        }
    };

    const handleGoogleLogin = async () => {
        setStatus(null);
        try {
            const provider = new GoogleAuthProvider();
            const result = await signInWithPopup(auth, provider);
            const roleDoc = await getDoc(doc(db, 'roles', result.user.uid));
            const role = roleDoc.exists() ? roleDoc.data().role : null;
            onLogin(result.user, role);
        } catch (err) {
            setStatus(err.message);
        }
    };

    const handlePasswordReset = async () => {
        if (!email) return setStatus('Enter your email first.');
        try {
            await sendPasswordResetEmail(auth, email);
            setStatus('Password reset email sent.');
        } catch (err) {
            setStatus(err.message);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100 font-sans">
            <div className="bg-white p-8 rounded shadow-md text-center w-full max-w-sm">
                <h2 className="text-2xl font-semibold mb-4">Admin Login</h2>

                <input
                    type="email"
                    placeholder="Email"
                    className="w-full border p-2 mb-2"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                />
                <input
                    type="password"
                    placeholder="Password"
                    className="w-full border p-2 mb-2"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                />

                <div className="flex justify-between mb-4">
                    <button
                        onClick={handleEmailLogin}
                        className="bg-blue-600 text-white px-4 py-2 rounded"
                    >
                        Login
                    </button>
                    <button
                        onClick={handlePasswordReset}
                        className="text-blue-600 underline text-sm"
                    >
                        Forgot Password?
                    </button>
                </div>

                <button
                    onClick={handleGoogleLogin}
                    className="bg-gray-200 px-4 py-2 rounded w-full"
                >
                    Sign in with Google
                </button>

                {status && <p className="text-red-500 mt-4 text-sm">{status}</p>}
            </div>
        </div>
    );
};

export default Auth;