import React, { useState } from 'react';
import { auth, db } from '../firebase';
import { createUserWithEmailAndPassword } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';

const InviteEditor = () => {
    const [showModal, setShowModal] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [role, setRole] = useState('editor');
    const [status, setStatus] = useState(null);

    const handleInvite = async () => {
        try {
            const cred = await createUserWithEmailAndPassword(auth, email, password);
            await setDoc(doc(db, 'roles', cred.user.uid), { role });
            setStatus('User invited successfully.');
            setShowModal(false);
            setEmail('');
            setPassword('');
            setRole('editor');
        } catch (err) {
            setStatus(`Error: ${err.message}`);
        }
    };

    return (
        <>
            <button
                onClick={() => setShowModal(true)}
                className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 text-sm"
            >
                + Invite User
            </button>

            {showModal && (
                <div className="fixed inset-0 bg-black bg-opacity-60 flex justify-center items-center z-50">
                    <div className="bg-white rounded-lg p-6 w-full max-w-md">
                        <h2 className="text-lg font-semibold mb-4">Invite New User</h2>
                        <input
                            type="email"
                            placeholder="Email"
                            className="w-full border p-2 mb-2"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                        />
                        <input
                            type="password"
                            placeholder="Temporary Password"
                            className="w-full border p-2 mb-2"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                        />
                        <select
                            className="w-full border p-2 mb-4"
                            value={role}
                            onChange={(e) => setRole(e.target.value)}
                        >
                            <option value="editor">Editor</option>
                            <option value="admin">Admin</option>
                        </select>
                        <div className="flex justify-between">
                            <button onClick={handleInvite} className="bg-green-600 text-white px-4 py-2 rounded">
                                Invite
                            </button>
                            <button onClick={() => setShowModal(false)} className="text-sm underline">
                                Cancel
                            </button>
                        </div>
                        {status && <p className="text-sm text-red-500 mt-2">{status}</p>}
                    </div>
                </div>
            )}
        </>
    );
};

export default InviteEditor;